MAX_FILE_SIZE = 1024 * 1024  # 1MB
MANIFEST_OLD_PATH = "META-INF/MANIFEST.MF"

def take(n, l):
    for i, item in enumerate(l):
        if i > n:
            break
        yield item

class Jar:
    def __init__(self, path):
        self.path = path
        self._manifest = {}
        self._dirlist = []

    def _parse_manifest(self, lines):
        version_indication = "version="
        version_lines = [line for line in lines if line.startswith(version_indication)]

        if len(version_lines) > 0:
            version = version_lines[0][len(version_indication):]
            yield 'Version', version.strip()

        field_names = ['Specification-Version', 'Specification-Title', 'Specification-Vendor', 'Implementation-Version', 'Implementation-Title', 'Implementation-Vendor']
        for line in lines:
            if any(line.startswith(field_name) for field_name in field_names):
                    key, value = line.split(':')
                    yield key.strip(), value.strip()

    def _open(self):
        if not zipfile.is_zipfile(self.path):
            raise ValueError("path is not a zip file: {}".format(self.path))
        return zipfile.ZipFile(self.path)

    def _read_dirlist(self):
        with self._open() as zf:
            filenames = dict(p for p in zf.namelist())
            return [f for f in filenames if any(r.search(f.lower()) for r in args.dirlist)]



    def _get_manifest_path(self, zf):
        for path in [args.manifest_path, MANIFEST_OLD_PATH]:
            if path in zf.namelist():
                return path

    def _read_manifest(self, throw_on_error=False):
        try:
            with self._open() as zf:
                manifest_path = self._get_manifest_path(zf)
                if not manifest_path:
                    # Not found manifest file
                    return {}

                manifest_info = zf.getinfo(manifest_path)
                if manifest_info.file_size > MAX_FILE_SIZE:
                    raise IOError("manifest file is too big")

                with zf.open(manifest_path) as f:
                    readline_f = functools.partial(f.readline, MAX_FILE_SIZE)
                    manifest_lines = list(x.decode().strip() for x in iter(readline_f, b''))
                    manifest = self._parse_manifest(manifest_lines)
                    return dict((k, v) for k, v in manifest
                            if not args.manifest_keys or any(m.search(k.lower()) for m in args.manifest_keys))
        except:
            sys.stderr.write("error while reading manifest of '{}': {}\n".format(self.path, traceback.format_exc()))

            if throw_on_error:
                raise

            return {}

    def manifest(self, throw_on_error=False):
        if not self._manifest:
            self._manifest = self._read_manifest(throw_on_error)
        return self._"}
